effect.shader:
void main() {
    vec2 p = acScreenNorm - center;
    p.x *= acAspect;
    float r = length(p);
    if (r <= 0.001) { fragColor = vec4(0.0, 0.0, 0.0, 1.0); return; }

    float t = clamp(1.0 - r / radius, 0.0, 1.0);
    float ang = atan(p.y, p.x) + swirl * t;
    float raioNovo = r / (1.0 + pull * t * t);
    vec2 q = vec2(cos(ang), sin(ang)) * raioNovo;
    q.x /= acAspect;

    vec4 c = texture(inputImg, q + center);
    // Núcleo negro no meio
    float nucleo = smoothstep(0.02, 0.06, r);
    fragColor = vec4(c.rgb * nucleo, c.a);
}
